import csv, json, math, itertools

rows=list(csv.DictReader(open('/app/data/orders.csv')))
vans=json.load(open('/app/data/vans.json'))
R=6371.0
def rad(x): return math.radians(x)
def dlat(x1,y1,x2,y2):
    a=math.sin(rad((x2-x1)/2))**2+math.cos(rad(x1))*math.cos(rad(x2))*math.sin(rad((y2-y1)/2))**2
    return 2*R*math.asin(math.sqrt(a))
orders={r['order_id']:(float(r['lat']),float(r['lon']),int(r['demand_kg'])) for r in rows}
D=(float(vans['depot']['lat']),float(vans['depot']['lon']))
CAP={k:v['capacity_kg'] for k,v in vans['vans'].items()}
def dist(a,b): return dlat(a[0],a[1],b[0],b[1])
def pt(i): return orders[i] if i in orders else D
def route_dist(seq):
    loc=[D]+[orders[i] for i in seq]+[D]
    return sum(dist(loc[k],loc[k+1]) for k in range(len(loc)-1))
ids=list(orders.keys())
# all subsets up to capacity each, disjoint, covering all
cap={k:CAP[k] for k in ('V1','V2')}
best=None
for A in itertools.combinations(ids,3):  # V1 gets 3, V2 gets 3
    B=tuple(i for i in ids if i not in A)
    sumA=sum(orders[i][2] for i in A); sumB=sum(orders[i][2] for i in B)
    if sumA>cap['V1'] or sumB>cap['V2']: continue
    for pA in itertools.permutations(A):
        for pB in itertools.permutations(B):
            total=route_dist(pA)+route_dist(pB)
            if best is None or total<best[0]:
                best=(total,dict(V1=list(pA),V2=list(pB)))
print(best)
json.dump({'routes':{'V1':best[1]['V1'],'V2':best[1]['V2']},'total_km':round(best[0],2)},open('/app/output/plan.json','w'),indent=2)
EOF
